INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI001', 'HDSAT-RW-M26-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Louisiana Purchase (French: Vente de la Louisiane, lit. ''Sale of Louisiana'') was the acquisition of the territory of Louisiana by the United States from the French First Republic in 1803. This consisted of most of the land in the Mississippi River''s drainage basin west of the river. In return for $15 million, or approximately $18 per square mile ($7/km2), the United States nominally acquired a total of 828,000 sq mi (2,140,000 km2; 530,000,000 acres) of land now in the Central United States. However, France only controlled a small fraction of this area, most of which was inhabited by Native Americans; effectively, for the majority of the area, the United States bought the preemptive right to obtain Indian lands by treaty or by conquest, to the exclusion of other colonial powers. The Kingdom of France had controlled the Louisiana territory from 1682 until it was ceded to Spain in 1762. In 1800, Napoleon Bonaparte, the First Consul of the French Republic, regained ownership of Louisiana in exchange for territories in Tuscany as part of a broader effort to re-establish a French colonial empire in North America. However, France''s failure to suppress a revolt in Saint-Domingue in the Caribbean, coupled with the prospect of renewed warfare with the United Kingdom, prompted Napoleon to consider selling Louisiana to the United States.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The 1803 Louisiana Purchase transferred a vast territory from France to the United States, though France controlled little of it."}, {"id": "B", "text": "France sold Louisiana to Spain in 1803."}, {"id": "C", "text": "The purchase gave the United States full control of settled Native lands."}, {"id": "D", "text": "The Louisiana Purchase was a military conquest of French Canada."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Louisiana Purchase", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Louisiana_Purchase', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI001', 'A', ARRAY['A']::TEXT[], 'The passage describes the purchase''s size, price, limited French control, and background.', '{"D": "The text describes an acquisition of territory from the French First Republic in 1803.", "B": "The text says France had ceded Louisiana to Spain in 1762, then regained it in 1800.", "C": "The text says the United States bought the preemptive right to obtain Indian lands by treaty or conquest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF001', 'HDSAT-RW-M26-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Louisiana Purchase (French: Vente de la Louisiane, lit. ''Sale of Louisiana'') was the acquisition of the territory of Louisiana by the United States from the French First Republic in 1803. This consisted of most of the land in the Mississippi River''s drainage basin west of the river. In return for $15 million, or approximately $18 per square mile ($7/km2), the United States nominally acquired a total of 828,000 sq mi (2,140,000 km2; 530,000,000 acres) of land now in the Central United States. However, France only controlled a small fraction of this area, most of which was inhabited by Native Americans; effectively, for the majority of the area, the United States bought the preemptive right to obtain Indian lands by treaty or by conquest, to the exclusion of other colonial powers. The Kingdom of France had controlled the Louisiana territory from 1682 until it was ceded to Spain in 1762. In 1800, Napoleon Bonaparte, the First Consul of the French Republic, regained ownership of Louisiana in exchange for territories in Tuscany as part of a broader effort to re-establish a French colonial empire in North America. However, France''s failure to suppress a revolt in Saint-Domingue in the Caribbean, coupled with the prospect of renewed warfare with the United Kingdom, prompted Napoleon to consider selling Louisiana to the United States.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF001', 'B', ARRAY['B']::TEXT[], 'The United States bought a legal claim, not effective control, over most of the territory.', '{"D": "The text says the United States bought the preemptive right to obtain Indian lands by treaty or conquest.", "C": "French control was limited, and Native peoples inhabited most of the area.", "A": "The purchase covered 828,000 square miles."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS001', 'HDSAT-RW-M26-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Louisiana Purchase (French: Vente de la Louisiane, lit. ''Sale of Louisiana'') was the acquisition of the territory of Louisiana by the United States from the French First Republic in 1803. This consisted of most of the land in the Mississippi River''s drainage basin west of the river. In return for $15 million, or approximately $18 per square mile ($7/km2), the United States nominally acquired a total of 828,000 sq mi (2,140,000 km2; 530,000,000 acres) of land now in the Central United States. However, France only controlled a small fraction of this area, most of which was inhabited by Native Americans; effectively, for the majority of the area, the United States bought the preemptive right to obtain Indian lands by treaty or by conquest, to the exclusion of other colonial powers. The Kingdom of France had controlled the Louisiana territory from 1682 until it was ceded to Spain in 1762. In 1800, Napoleon Bonaparte, the First Consul of the French Republic, regained ownership of Louisiana in exchange for territories in Tuscany as part of a broader effort to re-establish a French colonial empire in North America. However, France''s failure to suppress a revolt in Saint-Domingue in the Caribbean, coupled with the prospect of renewed warfare with the United Kingdom, prompted Napoleon to consider selling Louisiana to the United States.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares the Louisiana Purchase with the Alaska Purchase."}, {"id": "B", "text": "It describes the purchase and its terms, explains the limited French control, and recounts how France acquired and sold the territory."}, {"id": "C", "text": "It argues that the purchase was unconstitutional."}, {"id": "D", "text": "It narrates the Lewis and Clark expedition."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Louisiana Purchase", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Louisiana_Purchase', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS001', 'B', ARRAY['B']::TEXT[], 'The passage moves from the deal''s terms to its real meaning and background.', '{"D": "The expedition is not mentioned.", "A": "The Alaska Purchase is not mentioned.", "C": "Constitutionality is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE001', 'HDSAT-RW-M26-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Louisiana Purchase (French: Vente de la Louisiane, lit. ''Sale of Louisiana'') was the acquisition of the territory of Louisiana by the United States from the French First Republic in 1803. This consisted of most of the land in the Mississippi River''s drainage basin west of the river. In return for $15 million, or approximately $18 per square mile ($7/km2), the United States nominally acquired a total of 828,000 sq mi (2,140,000 km2; 530,000,000 acres) of land now in the Central United States. However, France only controlled a small fraction of this area, most of which was inhabited by Native Americans; effectively, for the majority of the area, the United States bought the preemptive right to obtain Indian lands by treaty or by conquest, to the exclusion of other colonial powers. The Kingdom of France had controlled the Louisiana territory from 1682 until it was ceded to Spain in 1762. In 1800, Napoleon Bonaparte, the First Consul of the French Republic, regained ownership of Louisiana in exchange for territories in Tuscany as part of a broader effort to re-establish a French colonial empire in North America. However, France''s failure to suppress a revolt in Saint-Domingue in the Caribbean, coupled with the prospect of renewed warfare with the United Kingdom, prompted Napoleon to consider selling Louisiana to the United States.', 'Which quotation from the text most directly supports the claim that the United States bought claims rather than settled control?', '[{"id": "A", "text": "The Louisiana Purchase was the acquisition of the territory of Louisiana by the United States from the French First Republic in 1803."}, {"id": "B", "text": "The Kingdom of France had controlled the Louisiana territory from 1682 until it was ceded to Spain in 1762."}, {"id": "C", "text": "However, France only controlled a small fraction of this area, most of which was inhabited by Native Americans; effectively, for the majority of the area, the United States bought the preemptive right to obtain Indian lands by treaty or by conquest, to the exclusion of other colonial powers."}, {"id": "D", "text": "In return for $15 million the United States nominally acquired a total of 828,000 sq mi of land."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Louisiana Purchase", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Louisiana_Purchase', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE001', 'C', ARRAY['C']::TEXT[], 'The correct quotation explains that the United States acquired preemptive rights over Native lands.', '{"A": "This sentence defines the purchase.", "D": "This sentence gives the price and area.", "B": "This sentence describes earlier French control."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI002', 'HDSAT-RW-M26-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The War of 1812 was a conflict initiated by the United States against the United Kingdom and its allies fought mainly in North America and at sea during the wider Napoleonic Wars. The United States declared war on Britain on 18 June 1812. Although peace terms were agreed upon in the December 1814 Treaty of Ghent, the war did not officially end until the peace treaty was ratified by the United States Senate on 17 February 1815. The United States objected to British restrictions on American trade with Napoleonic France and to the Royal Navy''s impressment of seamen from American vessels, including men the United States considered American citizens. Opinion in the US was split on how to respond, and although majorities in both the House and Senate voted for war in June 1812, they were divided along strict party lines, with the Democratic-Republican Party in favour and the Federalist Party against. News of British concessions made in an attempt to avoid war did not reach the US until late July, by which time the conflict was already underway. Britain, engaged in a global war against France, defended its maritime system as necessary to the defeat of Napoleon and treated many impressed sailors as British subjects. Tensions were also intensified by British relations with Indigenous confederacies resisting American expansion in the Old Northwest.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The War of 1812 was fought between the United States and France."}, {"id": "B", "text": "Americans unanimously supported the war."}, {"id": "C", "text": "The war ended immediately after the Declaration of War in 1812."}, {"id": "D", "text": "The War of 1812 grew out of maritime disputes with Britain, divided American opinion, and ended with the Treaty of Ghent."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "War of 1812", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/War_of_1812', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI002', 'D', ARRAY['D']::TEXT[], 'The passage describes the war''s causes, declaration, political division, and conclusion.', '{"A": "The text says the conflict was against the United Kingdom and its allies.", "C": "The text says the war lasted until 1815.", "B": "The text says opinion was split, with Federalists opposed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF002', 'HDSAT-RW-M26-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The War of 1812 was a conflict initiated by the United States against the United Kingdom and its allies fought mainly in North America and at sea during the wider Napoleonic Wars. The United States declared war on Britain on 18 June 1812. Although peace terms were agreed upon in the December 1814 Treaty of Ghent, the war did not officially end until the peace treaty was ratified by the United States Senate on 17 February 1815. The United States objected to British restrictions on American trade with Napoleonic France and to the Royal Navy''s impressment of seamen from American vessels, including men the United States considered American citizens. Opinion in the US was split on how to respond, and although majorities in both the House and Senate voted for war in June 1812, they were divided along strict party lines, with the Democratic-Republican Party in favour and the Federalist Party against. News of British concessions made in an attempt to avoid war did not reach the US until late July, by which time the conflict was already underway. Britain, engaged in a global war against France, defended its maritime system as necessary to the defeat of Napoleon and treated many impressed sailors as British subjects. Tensions were also intensified by British relations with Indigenous confederacies resisting American expansion in the Old Northwest.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF002', 'C', ARRAY['C']::TEXT[], 'Slow communication meant the war started before the concessions could affect the decision.', '{"D": "The text says the conflict was already underway by the time the news arrived.", "B": "The text says the war continued until 1815.", "A": "The text says the United States declared war on 18 June 1812."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS002', 'HDSAT-RW-M26-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The War of 1812 was a conflict initiated by the United States against the United Kingdom and its allies fought mainly in North America and at sea during the wider Napoleonic Wars. The United States declared war on Britain on 18 June 1812. Although peace terms were agreed upon in the December 1814 Treaty of Ghent, the war did not officially end until the peace treaty was ratified by the United States Senate on 17 February 1815. The United States objected to British restrictions on American trade with Napoleonic France and to the Royal Navy''s impressment of seamen from American vessels, including men the United States considered American citizens. Opinion in the US was split on how to respond, and although majorities in both the House and Senate voted for war in June 1812, they were divided along strict party lines, with the Democratic-Republican Party in favour and the Federalist Party against. News of British concessions made in an attempt to avoid war did not reach the US until late July, by which time the conflict was already underway. Britain, engaged in a global war against France, defended its maritime system as necessary to the defeat of Napoleon and treated many impressed sailors as British subjects. Tensions were also intensified by British relations with Indigenous confederacies resisting American expansion in the Old Northwest.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles James Madison."}, {"id": "B", "text": "It introduces the conflict, explains American grievances and divided opinion, and notes the delayed news and the treaty."}, {"id": "C", "text": "It compares the war with the American Revolution."}, {"id": "D", "text": "It narrates a single naval battle in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "War of 1812", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/War_of_1812', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS002', 'B', ARRAY['B']::TEXT[], 'The passage moves from the war''s origins to politics and diplomacy.', '{"D": "No battle is narrated.", "C": "The Revolution is not discussed.", "A": "Madison is not mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE002', 'HDSAT-RW-M26-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The War of 1812 was a conflict initiated by the United States against the United Kingdom and its allies fought mainly in North America and at sea during the wider Napoleonic Wars. The United States declared war on Britain on 18 June 1812. Although peace terms were agreed upon in the December 1814 Treaty of Ghent, the war did not officially end until the peace treaty was ratified by the United States Senate on 17 February 1815. The United States objected to British restrictions on American trade with Napoleonic France and to the Royal Navy''s impressment of seamen from American vessels, including men the United States considered American citizens. Opinion in the US was split on how to respond, and although majorities in both the House and Senate voted for war in June 1812, they were divided along strict party lines, with the Democratic-Republican Party in favour and the Federalist Party against. News of British concessions made in an attempt to avoid war did not reach the US until late July, by which time the conflict was already underway. Britain, engaged in a global war against France, defended its maritime system as necessary to the defeat of Napoleon and treated many impressed sailors as British subjects. Tensions were also intensified by British relations with Indigenous confederacies resisting American expansion in the Old Northwest.', 'Which quotation from the text most directly supports the claim that American grievances were about maritime rights?', '[{"id": "A", "text": "Opinion in the US was split on how to respond."}, {"id": "B", "text": "Although peace terms were agreed upon in the December 1814 Treaty of Ghent, the war did not officially end until 1815."}, {"id": "C", "text": "The United States objected to British restrictions on American trade with Napoleonic France and to the Royal Navy''s impressment of seamen from American vessels, including men the United States considered American citizens."}, {"id": "D", "text": "The War of 1812 was a conflict initiated by the United States against the United Kingdom and its allies."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "War of 1812", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/War_of_1812', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE002', 'C', ARRAY['C']::TEXT[], 'The correct quotation names trade restrictions and impressment of seamen.', '{"D": "This sentence introduces the conflict.", "B": "This sentence describes the treaty and timeline.", "A": "This sentence describes divided opinion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI003', 'HDSAT-RW-M26-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Trail of Tears was the forced displacement and ethnic cleansing of about 60,000 Native Americans of the "Five Civilized Tribes", including their black slaves, between 1830 and 1850 by the United States government. As part of Indian removal, members of the Cherokee, Muscogee, Seminole, Chickasaw, and Choctaw nations were forcibly removed from their ancestral homelands in the Southeastern United States to newly designated Indian Territory west of the Mississippi River after the passage of the Indian Removal Act in 1830. The Cherokee removal in 1838 was the last forced removal east of the Mississippi and was brought on by the discovery of gold near Dahlonega, Georgia, in 1828, resulting in the Georgia Gold Rush. The relocated peoples suffered from exposure, disease, and starvation while en route to their newly designated Indian reserve. Thousands died from disease before reaching their destinations or shortly after. A variety of scholars have classified the Trail of Tears as an example of the genocide of Native Americans; others categorize it as ethnic cleansing. == Overview == In 1830, a group of Indian nations collectively referred to as the "Five Civilized Tribes" (the Cherokee, Chickasaw, Choctaw, Muscogee, and Seminole nations), were living autonomously in what would later be termed the American Deep South.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Trail of Tears affected only the Cherokee nation."}, {"id": "B", "text": "The Trail of Tears took place before the Indian Removal Act."}, {"id": "C", "text": "The Trail of Tears was the forced removal of tens of thousands of Native Americans to Indian Territory, causing widespread death."}, {"id": "D", "text": "The Trail of Tears was a voluntary migration west by Native nations."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Trail of Tears", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Trail_of_Tears', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI003', 'C', ARRAY['C']::TEXT[], 'The passage defines the removal, identifies the nations involved, and describes its causes and toll.', '{"D": "The text describes forced displacement and ethnic cleansing.", "A": "The text names the Cherokee, Muscogee, Seminole, Chickasaw, and Choctaw.", "B": "The text says removal followed the 1830 Indian Removal Act."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF003', 'HDSAT-RW-M26-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Trail of Tears was the forced displacement and ethnic cleansing of about 60,000 Native Americans of the "Five Civilized Tribes", including their black slaves, between 1830 and 1850 by the United States government. As part of Indian removal, members of the Cherokee, Muscogee, Seminole, Chickasaw, and Choctaw nations were forcibly removed from their ancestral homelands in the Southeastern United States to newly designated Indian Territory west of the Mississippi River after the passage of the Indian Removal Act in 1830. The Cherokee removal in 1838 was the last forced removal east of the Mississippi and was brought on by the discovery of gold near Dahlonega, Georgia, in 1828, resulting in the Georgia Gold Rush. The relocated peoples suffered from exposure, disease, and starvation while en route to their newly designated Indian reserve. Thousands died from disease before reaching their destinations or shortly after. A variety of scholars have classified the Trail of Tears as an example of the genocide of Native Americans; others categorize it as ethnic cleansing. == Overview == In 1830, a group of Indian nations collectively referred to as the "Five Civilized Tribes" (the Cherokee, Chickasaw, Choctaw, Muscogee, and Seminole nations), were living autonomously in what would later be termed the American Deep South.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF003', 'A', ARRAY['A']::TEXT[], 'The gold discovery gave settlers and officials a strong economic interest in Cherokee land.', '{"D": "The text links the removal to the gold discovery and the resulting rush.", "B": "Gold is an economic motive.", "C": "The text describes forced removal by the United States government."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS003', 'HDSAT-RW-M26-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Trail of Tears was the forced displacement and ethnic cleansing of about 60,000 Native Americans of the "Five Civilized Tribes", including their black slaves, between 1830 and 1850 by the United States government. As part of Indian removal, members of the Cherokee, Muscogee, Seminole, Chickasaw, and Choctaw nations were forcibly removed from their ancestral homelands in the Southeastern United States to newly designated Indian Territory west of the Mississippi River after the passage of the Indian Removal Act in 1830. The Cherokee removal in 1838 was the last forced removal east of the Mississippi and was brought on by the discovery of gold near Dahlonega, Georgia, in 1828, resulting in the Georgia Gold Rush. The relocated peoples suffered from exposure, disease, and starvation while en route to their newly designated Indian reserve. Thousands died from disease before reaching their destinations or shortly after. A variety of scholars have classified the Trail of Tears as an example of the genocide of Native Americans; others categorize it as ethnic cleansing. == Overview == In 1830, a group of Indian nations collectively referred to as the "Five Civilized Tribes" (the Cherokee, Chickasaw, Choctaw, Muscogee, and Seminole nations), were living autonomously in what would later be termed the American Deep South.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles a single Cherokee family."}, {"id": "B", "text": "It defines the removal, identifies the nations and destination, and describes the Cherokee case and its suffering."}, {"id": "C", "text": "It compares the Trail of Tears with the Underground Railroad."}, {"id": "D", "text": "It argues that the removal was legal and just."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Trail of Tears", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Trail_of_Tears', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS003', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition and policy to the Cherokee removal and its consequences.', '{"A": "No family is profiled.", "C": "The Underground Railroad is not mentioned.", "D": "The text describes forced displacement and ethnic cleansing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE003', 'HDSAT-RW-M26-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Trail of Tears was the forced displacement and ethnic cleansing of about 60,000 Native Americans of the "Five Civilized Tribes", including their black slaves, between 1830 and 1850 by the United States government. As part of Indian removal, members of the Cherokee, Muscogee, Seminole, Chickasaw, and Choctaw nations were forcibly removed from their ancestral homelands in the Southeastern United States to newly designated Indian Territory west of the Mississippi River after the passage of the Indian Removal Act in 1830. The Cherokee removal in 1838 was the last forced removal east of the Mississippi and was brought on by the discovery of gold near Dahlonega, Georgia, in 1828, resulting in the Georgia Gold Rush. The relocated peoples suffered from exposure, disease, and starvation while en route to their newly designated Indian reserve. Thousands died from disease before reaching their destinations or shortly after. A variety of scholars have classified the Trail of Tears as an example of the genocide of Native Americans; others categorize it as ethnic cleansing. == Overview == In 1830, a group of Indian nations collectively referred to as the "Five Civilized Tribes" (the Cherokee, Chickasaw, Choctaw, Muscogee, and Seminole nations), were living autonomously in what would later be termed the American Deep South.', 'Which quotation from the text most directly supports the claim that removal caused severe suffering?', '[{"id": "A", "text": "The relocated peoples suffered from exposure, disease, and starvation while en route to their newly designated Indian reserve."}, {"id": "B", "text": "The Trail of Tears was the forced displacement and ethnic cleansing of about 60,000 Native Americans."}, {"id": "C", "text": "A variety of scholars have classified the Trail of Tears as an example of the genocide of Native Americans."}, {"id": "D", "text": "The Cherokee removal in 1838 was the last forced removal east of the Mississippi."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Trail of Tears", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Trail_of_Tears', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE003', 'A', ARRAY['A']::TEXT[], 'The correct quotation names exposure, disease, and starvation during the journey.', '{"B": "This sentence defines the event and its scale.", "D": "This sentence identifies the last removal.", "C": "This sentence describes scholarly classification."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI004', 'HDSAT-RW-M26-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The California gold rush (1848–1855) was a gold rush in California, which began on January 24, 1848, when gold was found by James W. Marshall at Sutter''s Mill in Coloma, California. The news of gold brought approximately 300,000 people from the rest of the United States and abroad to California, which had recently been conquered from Mexico. The sudden influx of gold into the money supply reinvigorated the American economy; the sudden population increase allowed California to grow rapidly into statehood in the Compromise of 1850. The gold rush had severe effects on Native Californians and accelerated the Native American population''s decline from factors including disease, starvation, and according to certain sources, acts of unprovoked aggression. The effects of the gold rush were substantial. The arrival of large numbers of "forty-niners" (referring to 1849, the peak year for gold rush immigration) led to significant conflict between the newcomers and indigenous people, eventually resulting in whole tribes being displaced in some cases. Outside of California, the first to arrive were from Oregon, Hawaii, and Latin America in late 1848. Of the approximately 300,000 people who came to California during the gold rush, about half arrived by sea and half came overland on the California Trail and the California Road; forty-niners often faced substantial hardships on the trip.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The California gold rush drew 300,000 people, boosted the economy and statehood, and devastated Native Californians."}, {"id": "B", "text": "The gold rush benefited Native Californians."}, {"id": "C", "text": "The gold rush delayed California''s statehood."}, {"id": "D", "text": "The gold rush was a small event that attracted few migrants."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "California gold rush", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/California_gold_rush', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI004', 'A', ARRAY['A']::TEXT[], 'The passage describes the discovery, the influx of migrants, and the economic and human consequences.', '{"D": "The text says about 300,000 people came to California.", "C": "The text says the population increase allowed California to grow rapidly into statehood.", "B": "The text says the gold rush accelerated the Native American population''s decline."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF004', 'HDSAT-RW-M26-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The California gold rush (1848–1855) was a gold rush in California, which began on January 24, 1848, when gold was found by James W. Marshall at Sutter''s Mill in Coloma, California. The news of gold brought approximately 300,000 people from the rest of the United States and abroad to California, which had recently been conquered from Mexico. The sudden influx of gold into the money supply reinvigorated the American economy; the sudden population increase allowed California to grow rapidly into statehood in the Compromise of 1850. The gold rush had severe effects on Native Californians and accelerated the Native American population''s decline from factors including disease, starvation, and according to certain sources, acts of unprovoked aggression. The effects of the gold rush were substantial. The arrival of large numbers of "forty-niners" (referring to 1849, the peak year for gold rush immigration) led to significant conflict between the newcomers and indigenous people, eventually resulting in whole tribes being displaced in some cases. Outside of California, the first to arrive were from Oregon, Hawaii, and Latin America in late 1848. Of the approximately 300,000 people who came to California during the gold rush, about half arrived by sea and half came overland on the California Trail and the California Road; forty-niners often faced substantial hardships on the trip.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF004', 'D', ARRAY['D']::TEXT[], 'A rapid population increase supported the transition to statehood in 1850.', '{"A": "The text says the population increase allowed California to grow rapidly into statehood.", "B": "The text describes 300,000 arrivals.", "C": "Nothing in the text concerns Pacific access."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS004', 'HDSAT-RW-M26-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The California gold rush (1848–1855) was a gold rush in California, which began on January 24, 1848, when gold was found by James W. Marshall at Sutter''s Mill in Coloma, California. The news of gold brought approximately 300,000 people from the rest of the United States and abroad to California, which had recently been conquered from Mexico. The sudden influx of gold into the money supply reinvigorated the American economy; the sudden population increase allowed California to grow rapidly into statehood in the Compromise of 1850. The gold rush had severe effects on Native Californians and accelerated the Native American population''s decline from factors including disease, starvation, and according to certain sources, acts of unprovoked aggression. The effects of the gold rush were substantial. The arrival of large numbers of "forty-niners" (referring to 1849, the peak year for gold rush immigration) led to significant conflict between the newcomers and indigenous people, eventually resulting in whole tribes being displaced in some cases. Outside of California, the first to arrive were from Oregon, Hawaii, and Latin America in late 1848. Of the approximately 300,000 people who came to California during the gold rush, about half arrived by sea and half came overland on the California Trail and the California Road; forty-niners often faced substantial hardships on the trip.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains mining technology in detail."}, {"id": "B", "text": "It compares the California and Klondike gold rushes."}, {"id": "C", "text": "It describes the discovery and migration, then explains the economic and demographic effects."}, {"id": "D", "text": "It narrates one miner''s journey overland."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "California gold rush", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/California_gold_rush', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS004', 'C', ARRAY['C']::TEXT[], 'The passage moves from the discovery to migration and consequences.', '{"D": "No individual miner is profiled.", "B": "The Klondike is not mentioned.", "A": "Mining technology is not described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE004', 'HDSAT-RW-M26-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The California gold rush (1848–1855) was a gold rush in California, which began on January 24, 1848, when gold was found by James W. Marshall at Sutter''s Mill in Coloma, California. The news of gold brought approximately 300,000 people from the rest of the United States and abroad to California, which had recently been conquered from Mexico. The sudden influx of gold into the money supply reinvigorated the American economy; the sudden population increase allowed California to grow rapidly into statehood in the Compromise of 1850. The gold rush had severe effects on Native Californians and accelerated the Native American population''s decline from factors including disease, starvation, and according to certain sources, acts of unprovoked aggression. The effects of the gold rush were substantial. The arrival of large numbers of "forty-niners" (referring to 1849, the peak year for gold rush immigration) led to significant conflict between the newcomers and indigenous people, eventually resulting in whole tribes being displaced in some cases. Outside of California, the first to arrive were from Oregon, Hawaii, and Latin America in late 1848. Of the approximately 300,000 people who came to California during the gold rush, about half arrived by sea and half came overland on the California Trail and the California Road; forty-niners often faced substantial hardships on the trip.', 'Which quotation from the text most directly supports the claim that the gold rush harmed Native Californians?', '[{"id": "A", "text": "The news of gold brought approximately 300,000 people to California."}, {"id": "B", "text": "The California gold rush was a gold rush in California, which began on January 24, 1848."}, {"id": "C", "text": "The sudden influx of gold into the money supply reinvigorated the American economy."}, {"id": "D", "text": "The gold rush had severe effects on Native Californians and accelerated the Native American population''s decline from factors including disease, starvation, and according to certain sources, acts of unprovoked aggression."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "California gold rush", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/California_gold_rush', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE004', 'D', ARRAY['D']::TEXT[], 'The correct quotation names disease, starvation, and aggression as causes of Native decline.', '{"B": "This sentence dates the discovery.", "A": "This sentence describes migration.", "C": "This sentence describes economic effects."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI005', 'HDSAT-RW-M26-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The American Civil War (April 12, 1861 – May 26, 1865; also known by other names) was a civil war in the United States between the Union ("the North") and the Confederacy ("the South"), which was formed in 1861 by Southern states that had seceded from the Union to preserve slavery in the United States. The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860 and the growing abolitionist movement in the North. The war ended with a Union victory, dissolution of the Confederacy and the national abolition of slavery, freeing four million African Americans. Decades of controversy over slavery came to a head when Lincoln, a Republican who opposed slavery''s expansion, won the 1860 presidential election. Seven slave states in the South responded to Lincoln''s victory by seceding from the United States and forming the Confederate States. The Confederate States seized United States forts and other federal assets in the South. The war began on April 12, 1861, when the Confederate States bombarded Fort Sumter in South Carolina. A wave of enthusiasm for war swept over the North and South, as military recruitment soared. Four more Southern states seceded after the war began and, led by its president Jefferson Davis, the Confederacy comprised eleven states, containing a third of the US population. Four years of intense combat, mostly in the South, ensued.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Civil War was fought between the Union and a Confederacy formed to preserve slavery, and it ended with Union victory and abolition."}, {"id": "B", "text": "The war ended without freeing any enslaved people."}, {"id": "C", "text": "The Civil War was fought between the United States and Britain."}, {"id": "D", "text": "The Confederacy was formed to abolish slavery."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "American Civil War", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/American_Civil_War', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI005', 'A', ARRAY['A']::TEXT[], 'The passage describes the war''s cause, outbreak, scale, and outcome.', '{"C": "The text names the Union and the Confederacy.", "D": "The text says Southern states seceded to preserve slavery.", "B": "The text says the war ended with national abolition of slavery, freeing four million African Americans."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF005', 'HDSAT-RW-M26-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The American Civil War (April 12, 1861 – May 26, 1865; also known by other names) was a civil war in the United States between the Union ("the North") and the Confederacy ("the South"), which was formed in 1861 by Southern states that had seceded from the Union to preserve slavery in the United States. The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860 and the growing abolitionist movement in the North. The war ended with a Union victory, dissolution of the Confederacy and the national abolition of slavery, freeing four million African Americans. Decades of controversy over slavery came to a head when Lincoln, a Republican who opposed slavery''s expansion, won the 1860 presidential election. Seven slave states in the South responded to Lincoln''s victory by seceding from the United States and forming the Confederate States. The Confederate States seized United States forts and other federal assets in the South. The war began on April 12, 1861, when the Confederate States bombarded Fort Sumter in South Carolina. A wave of enthusiasm for war swept over the North and South, as military recruitment soared. Four more Southern states seceded after the war began and, led by its president Jefferson Davis, the Confederacy comprised eleven states, containing a third of the US population. Four years of intense combat, mostly in the South, ensued.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF005', 'B', ARRAY['B']::TEXT[], 'With roughly twice the population, the Union could draw on more manpower.', '{"A": "A third of the population implies the Union held about two-thirds.", "C": "The Union''s larger population would support more troops.", "D": "The text says military recruitment soared in both sections."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS005', 'HDSAT-RW-M26-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The American Civil War (April 12, 1861 – May 26, 1865; also known by other names) was a civil war in the United States between the Union ("the North") and the Confederacy ("the South"), which was formed in 1861 by Southern states that had seceded from the Union to preserve slavery in the United States. The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860 and the growing abolitionist movement in the North. The war ended with a Union victory, dissolution of the Confederacy and the national abolition of slavery, freeing four million African Americans. Decades of controversy over slavery came to a head when Lincoln, a Republican who opposed slavery''s expansion, won the 1860 presidential election. Seven slave states in the South responded to Lincoln''s victory by seceding from the United States and forming the Confederate States. The Confederate States seized United States forts and other federal assets in the South. The war began on April 12, 1861, when the Confederate States bombarded Fort Sumter in South Carolina. A wave of enthusiasm for war swept over the North and South, as military recruitment soared. Four more Southern states seceded after the war began and, led by its president Jefferson Davis, the Confederacy comprised eleven states, containing a third of the US population. Four years of intense combat, mostly in the South, ensued.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares the Civil War with the Napoleonic Wars."}, {"id": "B", "text": "It profiles Jefferson Davis."}, {"id": "C", "text": "It defines the war and its cause, describes the secession and outbreak, and summarizes the conflict and outcome."}, {"id": "D", "text": "It narrates a single battle in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "American Civil War", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/American_Civil_War', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS005', 'C', ARRAY['C']::TEXT[], 'The passage moves from causes to secession and then to the war''s course and result.', '{"D": "Fort Sumter is mentioned as the start, not narrated.", "B": "Davis is named as president but not profiled.", "A": "The Napoleonic Wars are not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE005', 'HDSAT-RW-M26-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The American Civil War (April 12, 1861 – May 26, 1865; also known by other names) was a civil war in the United States between the Union ("the North") and the Confederacy ("the South"), which was formed in 1861 by Southern states that had seceded from the Union to preserve slavery in the United States. The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860 and the growing abolitionist movement in the North. The war ended with a Union victory, dissolution of the Confederacy and the national abolition of slavery, freeing four million African Americans. Decades of controversy over slavery came to a head when Lincoln, a Republican who opposed slavery''s expansion, won the 1860 presidential election. Seven slave states in the South responded to Lincoln''s victory by seceding from the United States and forming the Confederate States. The Confederate States seized United States forts and other federal assets in the South. The war began on April 12, 1861, when the Confederate States bombarded Fort Sumter in South Carolina. A wave of enthusiasm for war swept over the North and South, as military recruitment soared. Four more Southern states seceded after the war began and, led by its president Jefferson Davis, the Confederacy comprised eleven states, containing a third of the US population. Four years of intense combat, mostly in the South, ensued.', 'Which quotation from the text most directly supports the claim that slavery was central to secession?', '[{"id": "A", "text": "The war began on April 12, 1861, when the Confederate States bombarded Fort Sumter in South Carolina."}, {"id": "B", "text": "Four more Southern states seceded after the war began."}, {"id": "C", "text": "The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860 and the growing abolitionist movement in the North."}, {"id": "D", "text": "The American Civil War was a civil war in the United States between the Union and the Confederacy."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "American Civil War", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/American_Civil_War', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE005', 'C', ARRAY['C']::TEXT[], 'The correct quotation ties secession to fears that slavery was threatened.', '{"D": "This sentence defines the conflict.", "A": "This sentence describes the war''s first battle.", "B": "This sentence describes additional secessions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI006', 'HDSAT-RW-M26-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Reconstruction era, often simply called Reconstruction, was a period in United States history that followed the American Civil War (1861–1865) and was dominated by the legal, social, and political challenges of the abolition of slavery and federal control over, and reintegration of, the former Confederate States into the United States. Three amendments were added to the United States Constitution to grant citizenship and equal civil rights to the newly freed slaves. To circumvent these, former Confederate states imposed poll taxes and literacy tests and sought to intimidate and control the Black population and discourage or prevent them from voting. Throughout the war, the Union was confronted with the issue of how to administer captured areas and handle slaves escaping to Union lines. The United States Army played a vital role in establishing a free labor economy in the South, protecting freedmen''s rights and creating educational and religious institutions. Despite its reluctance to interfere with slavery, Congress passed the Confiscation Acts to seize Confederates'' slaves, providing a precedent for President Abraham Lincoln to issue the Emancipation Proclamation. Congress established a Freedmen''s Bureau to provide much-needed food and shelter to the newly freed slaves. As it became clear the Union would win, Congress debated the process for readmission of seceded states.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Reconstruction abolished the Constitution."}, {"id": "B", "text": "Reconstruction ended before the Civil War."}, {"id": "C", "text": "Reconstruction addressed abolition and readmission through constitutional amendments, but Southern states undermined freed people''s rights."}, {"id": "D", "text": "Reconstruction was a period of peace with no conflict over rights."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Reconstruction era", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Reconstruction_era', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI006', 'C', ARRAY['C']::TEXT[], 'The passage describes Reconstruction''s aims, amendments, federal efforts, and Southern resistance.', '{"D": "The text describes legal, social, and political challenges and resistance.", "A": "The text says three amendments were added to the Constitution.", "B": "The text says the period followed the American Civil War."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF006', 'HDSAT-RW-M26-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Reconstruction era, often simply called Reconstruction, was a period in United States history that followed the American Civil War (1861–1865) and was dominated by the legal, social, and political challenges of the abolition of slavery and federal control over, and reintegration of, the former Confederate States into the United States. Three amendments were added to the United States Constitution to grant citizenship and equal civil rights to the newly freed slaves. To circumvent these, former Confederate states imposed poll taxes and literacy tests and sought to intimidate and control the Black population and discourage or prevent them from voting. Throughout the war, the Union was confronted with the issue of how to administer captured areas and handle slaves escaping to Union lines. The United States Army played a vital role in establishing a free labor economy in the South, protecting freedmen''s rights and creating educational and religious institutions. Despite its reluctance to interfere with slavery, Congress passed the Confiscation Acts to seize Confederates'' slaves, providing a precedent for President Abraham Lincoln to issue the Emancipation Proclamation. Congress established a Freedmen''s Bureau to provide much-needed food and shelter to the newly freed slaves. As it became clear the Union would win, Congress debated the process for readmission of seceded states.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF006', 'D', ARRAY['D']::TEXT[], 'The stated purpose of the measures was to discourage or prevent Black voting.', '{"B": "The text says the measures were meant to circumvent the amendments and prevent Black people from voting.", "C": "Poll taxes and literacy tests restrict access rather than expand it.", "A": "The text presents them as workarounds to the amendments, not replacements."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS006', 'HDSAT-RW-M26-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The Reconstruction era, often simply called Reconstruction, was a period in United States history that followed the American Civil War (1861–1865) and was dominated by the legal, social, and political challenges of the abolition of slavery and federal control over, and reintegration of, the former Confederate States into the United States. Three amendments were added to the United States Constitution to grant citizenship and equal civil rights to the newly freed slaves. To circumvent these, former Confederate states imposed poll taxes and literacy tests and sought to intimidate and control the Black population and discourage or prevent them from voting. Throughout the war, the Union was confronted with the issue of how to administer captured areas and handle slaves escaping to Union lines. The United States Army played a vital role in establishing a free labor economy in the South, protecting freedmen''s rights and creating educational and religious institutions. Despite its reluctance to interfere with slavery, Congress passed the Confiscation Acts to seize Confederates'' slaves, providing a precedent for President Abraham Lincoln to issue the Emancipation Proclamation. Congress established a Freedmen''s Bureau to provide much-needed food and shelter to the newly freed slaves. As it became clear the Union would win, Congress debated the process for readmission of seceded states.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares Reconstruction with the New Deal."}, {"id": "B", "text": "It argues that Reconstruction succeeded completely."}, {"id": "C", "text": "It defines Reconstruction, describes the amendments and resistance to them, and explains federal and congressional action."}, {"id": "D", "text": "It profiles a single freedman''s life."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Reconstruction era", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Reconstruction_era', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS006', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to constitutional change, resistance, and federal measures.', '{"D": "No individual is profiled.", "A": "The New Deal is not mentioned.", "B": "The text describes how Southern states circumvented the amendments."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE006', 'HDSAT-RW-M26-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The Reconstruction era, often simply called Reconstruction, was a period in United States history that followed the American Civil War (1861–1865) and was dominated by the legal, social, and political challenges of the abolition of slavery and federal control over, and reintegration of, the former Confederate States into the United States. Three amendments were added to the United States Constitution to grant citizenship and equal civil rights to the newly freed slaves. To circumvent these, former Confederate states imposed poll taxes and literacy tests and sought to intimidate and control the Black population and discourage or prevent them from voting. Throughout the war, the Union was confronted with the issue of how to administer captured areas and handle slaves escaping to Union lines. The United States Army played a vital role in establishing a free labor economy in the South, protecting freedmen''s rights and creating educational and religious institutions. Despite its reluctance to interfere with slavery, Congress passed the Confiscation Acts to seize Confederates'' slaves, providing a precedent for President Abraham Lincoln to issue the Emancipation Proclamation. Congress established a Freedmen''s Bureau to provide much-needed food and shelter to the newly freed slaves. As it became clear the Union would win, Congress debated the process for readmission of seceded states.', 'Which quotation from the text most directly supports the claim that Southern states undermined new constitutional rights?', '[{"id": "A", "text": "The United States Army played a vital role in establishing a free labor economy in the South."}, {"id": "B", "text": "Congress established a Freedmen''s Bureau to provide much-needed food and shelter to the newly freed slaves."}, {"id": "C", "text": "Three amendments were added to the United States Constitution to grant citizenship and equal civil rights to the newly freed slaves."}, {"id": "D", "text": "To circumvent these, former Confederate states imposed poll taxes and literacy tests and sought to intimidate and control the Black population and discourage or prevent them from voting."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Reconstruction era", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Reconstruction_era', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE006', 'D', ARRAY['D']::TEXT[], 'The correct quotation names the poll taxes, literacy tests, and intimidation used to block voting.', '{"C": "This sentence describes the amendments.", "A": "This sentence describes the Army''s role.", "B": "This sentence describes the Freedmen''s Bureau."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI007', 'HDSAT-RW-M26-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A transcontinental railroad or transcontinental railway is contiguous railroad trackage that crosses a continental land mass and has terminals at different oceans or continental borders. Such networks may be via the tracks of a single railroad, or via several railroads owned or controlled by multiple railway companies along a continuous route. Although Europe is crisscrossed by railways, the railroads within Europe are usually not considered transcontinental, with the possible exception of the historic Orient Express. Transcontinental railroads helped open up interior regions of continents not previously colonized to exploration and settlement that would not otherwise have been feasible. In many cases, they also formed the backbones of cross-country passenger and freight transportation networks. Many of them continue to have an important role in freight transportation, and some such as the Trans-Siberian Railway even have passenger trains going from one end to the other. == Africa == === East-west === There are several ways to cross Africa transcontinentally via connecting east–west railways. One is the Benguela railway, completed in 1929. It starts in Lobito, Angola, and connects through Katanga to the Zambia railways system. From Zambia several ports are accessible on the Indian Ocean: Dar es Salaam in Tanzania through the TAZARA, and, through Zimbabwe, Beira and Maputo in Mozambique.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Transcontinental railroads cross a continent to link distant coasts and have opened interior regions and carried freight and passengers."}, {"id": "B", "text": "No transcontinental railroad remains in use today."}, {"id": "C", "text": "Transcontinental railroads are defined by crossing a single ocean."}, {"id": "D", "text": "Transcontinental railroads operate only within a single city."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Transcontinental railroad", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Transcontinental_railroad', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI007', 'A', ARRAY['A']::TEXT[], 'The passage defines transcontinental railroads, describes their effects, and gives examples.', '{"D": "The text says they cross a continental land mass with terminals at different oceans or borders.", "C": "The definition concerns continental crossings, not ocean crossings.", "B": "The text says many continue to play an important role in freight transportation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF007', 'HDSAT-RW-M26-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A transcontinental railroad or transcontinental railway is contiguous railroad trackage that crosses a continental land mass and has terminals at different oceans or continental borders. Such networks may be via the tracks of a single railroad, or via several railroads owned or controlled by multiple railway companies along a continuous route. Although Europe is crisscrossed by railways, the railroads within Europe are usually not considered transcontinental, with the possible exception of the historic Orient Express. Transcontinental railroads helped open up interior regions of continents not previously colonized to exploration and settlement that would not otherwise have been feasible. In many cases, they also formed the backbones of cross-country passenger and freight transportation networks. Many of them continue to have an important role in freight transportation, and some such as the Trans-Siberian Railway even have passenger trains going from one end to the other. == Africa == === East-west === There are several ways to cross Africa transcontinentally via connecting east–west railways. One is the Benguela railway, completed in 1929. It starts in Lobito, Angola, and connects through Katanga to the Zambia railways system. From Zambia several ports are accessible on the Indian Ocean: Dar es Salaam in Tanzania through the TAZARA, and, through Zimbabwe, Beira and Maputo in Mozambique.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF007', 'B', ARRAY['B']::TEXT[], 'Rail access to interior regions would make inland settlement more feasible.', '{"D": "Opening interior regions to settlement implies population movement inland.", "A": "That contradicts the stated effect.", "C": "The text says they formed backbones of freight networks."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-TS007', 'HDSAT-RW-M26-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A transcontinental railroad or transcontinental railway is contiguous railroad trackage that crosses a continental land mass and has terminals at different oceans or continental borders. Such networks may be via the tracks of a single railroad, or via several railroads owned or controlled by multiple railway companies along a continuous route. Although Europe is crisscrossed by railways, the railroads within Europe are usually not considered transcontinental, with the possible exception of the historic Orient Express. Transcontinental railroads helped open up interior regions of continents not previously colonized to exploration and settlement that would not otherwise have been feasible. In many cases, they also formed the backbones of cross-country passenger and freight transportation networks. Many of them continue to have an important role in freight transportation, and some such as the Trans-Siberian Railway even have passenger trains going from one end to the other. == Africa == === East-west === There are several ways to cross Africa transcontinentally via connecting east–west railways. One is the Benguela railway, completed in 1929. It starts in Lobito, Angola, and connects through Katanga to the Zambia railways system. From Zambia several ports are accessible on the Indian Ocean: Dar es Salaam in Tanzania through the TAZARA, and, through Zimbabwe, Beira and Maputo in Mozambique.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines transcontinental railroads, describes their effects, and gives examples from different regions."}, {"id": "B", "text": "It compares rail and air travel."}, {"id": "C", "text": "It narrates the construction of the Trans-Siberian Railway."}, {"id": "D", "text": "It argues that transcontinental railroads are obsolete."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Transcontinental railroad", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Transcontinental_railroad', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-TS007', 'A', ARRAY['A']::TEXT[], 'The passage moves from definition to consequences and examples.', '{"C": "The Trans-Siberian is mentioned only as an example.", "B": "Air travel is not discussed.", "D": "The text says many remain important for freight."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CE007', 'HDSAT-RW-M26-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A transcontinental railroad or transcontinental railway is contiguous railroad trackage that crosses a continental land mass and has terminals at different oceans or continental borders. Such networks may be via the tracks of a single railroad, or via several railroads owned or controlled by multiple railway companies along a continuous route. Although Europe is crisscrossed by railways, the railroads within Europe are usually not considered transcontinental, with the possible exception of the historic Orient Express. Transcontinental railroads helped open up interior regions of continents not previously colonized to exploration and settlement that would not otherwise have been feasible. In many cases, they also formed the backbones of cross-country passenger and freight transportation networks. Many of them continue to have an important role in freight transportation, and some such as the Trans-Siberian Railway even have passenger trains going from one end to the other. == Africa == === East-west === There are several ways to cross Africa transcontinentally via connecting east–west railways. One is the Benguela railway, completed in 1929. It starts in Lobito, Angola, and connects through Katanga to the Zambia railways system. From Zambia several ports are accessible on the Indian Ocean: Dar es Salaam in Tanzania through the TAZARA, and, through Zimbabwe, Beira and Maputo in Mozambique.', 'Which quotation from the text most directly supports the claim that transcontinental railroads enabled settlement?', '[{"id": "A", "text": "A transcontinental railroad is contiguous railroad trackage that crosses a continental land mass."}, {"id": "B", "text": "Many of them continue to have an important role in freight transportation."}, {"id": "C", "text": "Transcontinental railroads helped open up interior regions of continents not previously colonized to exploration and settlement that would not otherwise have been feasible."}, {"id": "D", "text": "Although Europe is crisscrossed by railways, the railroads within Europe are usually not considered transcontinental."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Transcontinental railroad", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Transcontinental_railroad', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CE007', 'C', ARRAY['C']::TEXT[], 'The correct quotation explicitly links the railroads to exploration and settlement.', '{"A": "This sentence defines the term.", "D": "This sentence discusses Europe''s railways.", "B": "This sentence describes freight''s continuing importance."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-CI008', 'HDSAT-RW-M26-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Homestead Acts were several laws in the United States by which an applicant could acquire ownership of government land or the public domain, typically called a homestead. In all, more than 160 million acres (650 thousand km2; 250 thousand sq mi) of public land, or nearly 10 percent of the total area of the United States, were given away free to 1.6 million homesteaders; most of the homesteads were west of the Mississippi River. An extension of the homestead principle in law, the Homestead Acts were an expression of the Free Soil policy of Northerners who wanted individual farmers to own and operate their own farms, as opposed to Southern slave owners who wanted to buy up large tracts of land and use slave labor, thereby shutting out free farmers. For a number of years individual Congressmen put forward bills providing for homesteading, but it was not until 1862 that the first homestead act was passed. The Homestead Act of 1862 opened up millions of acres. Any adult who had never taken up arms against the federal government of the United States could apply. Women and immigrants who had applied for citizenship were eligible. Most homesteading occurred during the period of 1900–1930. As of 2017, around 93 million Americans were descendants of people who received land through the Homestead Acts.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The Homestead Acts gave away vast public lands to settlers, reflecting Free Soil ideals and drawing millions of claimants."}, {"id": "B", "text": "The Homestead Acts required applicants to have served in the military."}, {"id": "C", "text": "The Homestead Acts applied only east of the Mississippi."}, {"id": "D", "text": "The Homestead Acts sold land only to wealthy slaveholders."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Homestead Acts", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Homestead_Acts', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-CI008', 'A', ARRAY['A']::TEXT[], 'The passage describes the acts'' scale, purpose, eligibility, and legacy.', '{"D": "The text says land was given free to 1.6 million homesteaders.", "C": "The text says most homesteads were west of the Mississippi.", "B": "The text says any adult who had not taken up arms against the federal government could apply."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M26-INF008', 'HDSAT-RW-M26-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The Homestead Acts were several laws in the United States by which an applicant could acquire ownership of government land or the public domain, typically called a homestead. In all, more than 160 million acres (650 thousand km2; 250 thousand sq mi) of public land, or nearly 10 percent of the total area of the United States, were given away free to 1.6 million homesteaders; most of the homesteads were west of the Mississippi River. An extension of the homestead principle in law, the Homestead Acts were an expression of the Free Soil policy of Northerners who wanted individual farmers to own and operate their own farms, as opposed to Southern slave owners who wanted to buy up large tracts of land and use slave labor, thereby shutting out free farmers. For a number of years individual Congressmen put forward bills providing for homesteading, but it was not until 1862 that the first homestead act was passed. The Homestead Act of 1862 opened up millions of acres. Any adult who had never taken up arms against the federal government of the United States could apply. Women and immigrants who had applied for citizenship were eligible. Most homesteading occurred during the period of 1900–1930. As of 2017, around 93 million Americans were descendants of people who received land through the Homestead Acts.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M26-INF008', 'A', ARRAY['A']::TEXT[], 'Eligibility for women and citizenship applicants widened access beyond male citizens.', '{"D": "The text names women and citizenship applicants as eligible.", "B": "That contradicts the stated eligibility.", "C": "The text does not require native birth."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
